import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import axios from 'axios';
import toast from 'react-hot-toast';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import './UserDashboard.css';

const UserDashboard = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [leads, setLeads] = useState([]);
  const [loading, setLoading] = useState(true);
  const [scraping, setScraping] = useState(false);
  const [scraperResults, setScraperResults] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [selectedLead, setSelectedLead] = useState(null);

  const [scraperData, setScraperData] = useState({
    city: 'Lahore', country: 'Pakistan', businessType: 'IT Company', maxResults: 10
  });

  const { user, logout, token } = useAuth();
  const navigate = useNavigate();

  const [stats, setStats] = useState({ totalLeads: 0, savedLeads: 0, cities: 0, emails: 0 });

  useEffect(() => { fetchLeads(); }, []);

  const fetchLeads = async () => {
    try {
      const response = await axios.get('/api/leads', { // ✅ Note the /api prefix if your backend uses it
        headers: { Authorization: `Bearer ${token}` }
      });
      const data = response.data.data || [];
      setLeads(data);

      const saved = data.filter(l => l.isSaved);
      const cities = [...new Set(data.map(l => l.city).filter(Boolean))];
      const emails = data.filter(l => l.email).length;

      setStats({ totalLeads: data.length, savedLeads: saved.length, cities: cities.length, emails: emails });
    } catch (error) {
      console.error("Fetch Error:", error);
      toast.error('Failed to load leads');
    } finally {
      setLoading(false);
    }
  };

  const handleScraperChange = (e) => setScraperData({ ...scraperData, [e.target.name]: e.target.value });
  const quickNiche = (niche) => setScraperData({ ...scraperData, businessType: niche });

  const runScraper = async () => {
    const { city, country, businessType, maxResults } = scraperData;
    if (!city || !businessType) return toast.error('City and Business Type are required');

    setScraping(true);
    setScraperResults([]);
    toast.loading('🌐 Scraping Google Maps...');

    try {
      const response = await axios.post('/api/scraper/run', {
        city, country, businessType, maxResults: parseInt(maxResults)
      }, { headers: { Authorization: `Bearer ${token}` } });

      if (response.data.success) {
        toast.dismiss();
        toast.success(`✅ Found ${response.data.count} leads!`);
        const scrapedLeads = response.data.leads || [];
        setScraperResults(scrapedLeads);

        if (scrapedLeads.length > 0) {
          toast.loading(`💾 Auto-saving ${scrapedLeads.length} leads...`);
          let savedCount = 0;
          for (let lead of scrapedLeads) {
            try {
              // ✅ SEND TO BACKEND
              const saveRes = await axios.post('/api/leads', lead, {
                headers: { Authorization: `Bearer ${token}` }
              });
              if(saveRes.data.success) savedCount++;
            } catch (e) { console.error("Save Error:", e); }
          }
          toast.dismiss();
          toast.success(`✅ ${savedCount} leads saved to "My Leads"!`);
          fetchLeads();
          setActiveTab('leads');
        }
      } else {
        toast.dismiss();
        toast.error(response.data.message || 'Scraper failed');
      }
    } catch (error) {
      toast.dismiss();
      console.error('Scraper Error:', error);
      toast.error(error.response?.data?.message || 'Failed to scrape.');
    } finally {
      setScraping(false);
    }
  };

  const handleSaveLead = async (leadId) => {
    try {
      await axios.put(`/api/leads/${leadId}/save`, {}, { headers: { Authorization: `Bearer ${token}` } });
      toast.success('⭐ Lead saved!');
      fetchLeads();
    } catch (error) { toast.error('Failed to save'); }
  };

  const handleUnsaveLead = async (leadId) => {
    try {
      await axios.put(`/api/leads/${leadId}/unsave`, {}, { headers: { Authorization: `Bearer ${token}` } });
      toast.success('Lead unsaved');
      fetchLeads();
    } catch (error) { toast.error('Failed to unsave'); }
  };

  const handleLogout = () => { logout(); navigate('/login'); toast.success('Logged out'); };
  const toggleTheme = () => { setIsDarkMode(!isDarkMode); document.body.classList.toggle('light-theme'); };

  const filteredLeads = leads.filter(lead =>
    lead.companyName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lead.industry?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lead.city?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <div className="loading-container"><div className="loader"></div><p>Loading...</p></div>;

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: 'fa-solid fa-gauge-high' },
    { id: 'scraper', label: 'Lead Scraper', icon: 'fa-solid fa-magnifying-glass-location' },
    { id: 'leads', label: 'My Leads', icon: 'fa-solid fa-users' },
    { id: 'analytics', label: 'Analytics', icon: 'fa-solid fa-chart-line' },
    { id: 'settings', label: 'Settings', icon: 'fa-solid fa-sliders' }
  ];

  const LeadDetailModal = ({ lead, onClose }) => {
    if (!lead) return null;
    return (
      <div className="modal-overlay" onClick={onClose}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={onClose}>×</button>
          <h2 className="modal-title"><i className="fa-solid fa-building"></i> {lead.companyName}</h2>
          <div className="modal-body">
            <div className="modal-row"><strong>Industry:</strong> {lead.industry || 'N/A'}</div>
            <div className="modal-row"><strong>Email:</strong> {lead.email || 'N/A'}</div>
            <div className="modal-row"><strong>Phone:</strong> {lead.phone || 'N/A'}</div>
            <div className="modal-row"><strong>Website:</strong> {lead.website ? <a href={lead.website} target="_blank">{lead.website}</a> : 'N/A'}</div>
            <div className="modal-row"><strong>Address:</strong> {lead.address || 'N/A'}</div>
            <div className="modal-row"><strong>City/Country:</strong> {lead.city || 'N/A'}, {lead.country || 'N/A'}</div>
          </div>
          <div className="modal-actions">
            {lead.isSaved ? (
              <button onClick={() => { handleUnsaveLead(lead._id); onClose(); }} className="unsave-btn">Unsave</button>
            ) : (
              <button onClick={() => { handleSaveLead(lead._id); onClose(); }} className="save-btn">Save</button>
            )}
            <button onClick={onClose} className="close-btn">Close</button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className={`user-dashboard ${isDarkMode ? 'dark' : 'light'}`}>
      {selectedLead && <LeadDetailModal lead={selectedLead} onClose={() => setSelectedLead(null)} />}

      <aside className="sidebar">
        <div className="sidebar-brand">
          <div className="brand-icon"><i className="fa-solid fa-crosshairs"></i></div>
          <div className="brand-text"><h2>LeadHunter</h2><span>Pro</span></div>
        </div>
        <nav className="sidebar-nav">
          {navItems.map(item => (
            <button key={item.id} className={`nav-item ${activeTab === item.id ? 'active' : ''}`} onClick={() => setActiveTab(item.id)}>
              <i className={item.icon}></i><span>{item.label}</span>
              {item.id === 'leads' && <span className="badge">{leads.filter(l => l.isSaved).length}</span>}
            </button>
          ))}
        </nav>
        <div className="sidebar-footer">
          <div className="user-info">
            <div className="avatar">{user?.name?.charAt(0) || 'U'}</div>
            <div className="user-details"><p className="name">{user?.name || 'User'}</p><p className="role">{user?.role || 'User'}</p></div>
          </div>
          <button onClick={handleLogout} className="logout-btn"><i className="fa-solid fa-power-off"></i></button>
        </div>
      </aside>

      <main className="main-content">
        {/* ... Rest of your existing rendering logic can go here (I am pasting the fixed Leads tab below) ... */}

        {activeTab === 'leads' && (
          <div className="tab-content leads-tab">
            <div className="leads-header">
              <div className="leads-search">
                <i className="fa-solid fa-search"></i>
                <input type="text" placeholder="Search leads..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
              </div>
              <span className="leads-count">{leads.filter(l => l.isSaved).length} Saved</span>
            </div>
            <div className="leads-grid">
              {filteredLeads.length === 0 ? (
                <div className="empty-state"><i className="fa-solid fa-inbox"></i><p>No leads found</p></div>
              ) : (
                filteredLeads.map(lead => (
                  <div key={lead._id} className="lead-card clickable" onClick={() => setSelectedLead(lead)}>
                    <div className="lead-card-header">
                      <h3>{lead.companyName}</h3>
                      <span className={`status-badge ${lead.status}`}>{lead.status}</span>
                    </div>
                    <div className="lead-card-body">
                      {lead.industry && <p><i className="fa-solid fa-tag"></i> {lead.industry}</p>}
                      {lead.city && <p><i className="fa-solid fa-location-dot"></i> {lead.city}, {lead.country}</p>}
                      {lead.phone && <p><i className="fa-solid fa-phone"></i> {lead.phone}</p>}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {/* NOTE: Paste your Dashboard, Scraper, Analytics, Settings tabs here from your previous working code */}
      </main>
    </div>
  );
};

export default UserDashboard;
